#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-17

# Security Tests: announce-release never emits the token reference value
#
# CodeQL js/clear-text-logging #406: the 401 path in scripts/announce-release.mjs
# printed the resolved HQ_API_TOKEN_REFERENCE value, an op:// path naming a real
# vault and item, into CI logs of this public repository. The fix removed the
# variable read entirely; the message names the repository VARIABLE and nothing
# else. This test fails if any console/summary/output call carries the
# identifier again, if the value is interpolated anywhere, or if the env read
# comes back.
#
# Allowed: the literal phrase "named by the HQ_API_TOKEN_REFERENCE repository
# variable" inside a message string. That is a name, not a value.
#
# Test Count: 3
# Priority: HIGH

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
SCRIPT="$PROJECT_ROOT/scripts/announce-release.mjs"

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m'

TESTS_PASSED=0
TESTS_FAILED=0

log_pass() { echo -e "  ${GREEN}✓${NC} $1"; TESTS_PASSED=$((TESTS_PASSED + 1)); }
log_fail() { echo -e "  ${RED}✗${NC} $1"; TESTS_FAILED=$((TESTS_FAILED + 1)); }
log_section() { echo -e "\n${YELLOW}$1${NC}"; }

if [[ ! -f "$SCRIPT" ]]; then
  echo "FAIL: $SCRIPT not found"
  exit 1
fi

ALLOWED='named by the HQ_API_TOKEN_REFERENCE repository variable'

log_section "Token reference: output sinks"

# Every line that invokes an output sink, minus the allowed naming phrase,
# must not contain the identifier. grep exits 1 on zero matches, so the
# empty-result path is handled by the || true guard, not by set -e.
SINK_HITS="$(grep -nE '(console\.[a-z]+|die|summary|output)\s*\(' "$SCRIPT" \
  | sed "s/${ALLOWED}//g" \
  | grep 'HQ_API_TOKEN_REFERENCE' || true)"

if [[ -z "$SINK_HITS" ]]; then
  log_pass "no console/die/summary/output call carries HQ_API_TOKEN_REFERENCE"
else
  log_fail "output call carries HQ_API_TOKEN_REFERENCE (print the variable name, never the value):"
  echo "$SINK_HITS" | head -20 | sed 's/^/      /'
fi

log_section "Token reference: value interpolation"

# A sink can span lines, so also scan the whole file (comment lines excluded)
# for the identifier anywhere outside the allowed naming phrase.
VALUE_HITS="$(grep -vE '^[[:space:]]*//' "$SCRIPT" \
  | sed "s/${ALLOWED}//g" \
  | grep -n 'HQ_API_TOKEN_REFERENCE' || true)"

if [[ -z "$VALUE_HITS" ]]; then
  log_pass "identifier appears only inside the allowed naming phrase"
else
  log_fail "HQ_API_TOKEN_REFERENCE used as a value outside the allowed phrase:"
  echo "$VALUE_HITS" | head -20 | sed 's/^/      /'
fi

log_section "Token reference: environment read"

READ_HITS="$(grep -nE 'process\.env\.HQ_API_TOKEN_REFERENCE|HQ_API_TOKEN_REFERENCE[[:space:]]*[,=}]' "$SCRIPT" \
  | grep -vE '^[0-9]+:[[:space:]]*//' || true)"

if [[ -z "$READ_HITS" ]]; then
  log_pass "script does not read or bind the reference variable"
else
  log_fail "script reads HQ_API_TOKEN_REFERENCE from the environment (remove the read):"
  echo "$READ_HITS" | head -20 | sed 's/^/      /'
fi

echo ""
echo "Passed: $TESTS_PASSED  Failed: $TESTS_FAILED"
if [[ $TESTS_FAILED -gt 0 ]]; then
  exit 1
fi
exit 0
